const runtimeMessages = Object.fromEntries(Object.entries(runtimeValues).map(([language, values]) => {
  if (values.length !== runtimeKeys.length) {
    throw new Error(`Invalid runtime translation count for ${language}: ${values.length}`);
  }
  return [language, Object.fromEntries(runtimeKeys.map((key, index) => [key, values[index]]))];
}));

