const localeMessages = Object.fromEntries(Object.entries(localizedValues).map(([language, values]) => {
  if (values.length !== localizedKeys.length) {
    throw new Error(`Invalid translation count for ${language}: ${values.length}`);
  }
  return [language, Object.fromEntries(localizedKeys.map((key, index) => [key, values[index]]))];
}));

function getStoredLanguage() {
  try {
    const saved = localStorage.getItem('muvy-language');
    return Object.hasOwn(languageCatalog, saved) ? saved : 'en';
  } catch {
    return 'en';
  }
}

let currentLanguage = getStoredLanguage();

function translateText(source) {
  const normalizedSource = source.replace(/[.!?]+$/, '');
  const direct = localeMessages[currentLanguage]?.[source] ?? localizedExtras[currentLanguage]?.[source] ?? localizedLateExtras[currentLanguage]?.[source] ?? localizedThemeLabels[currentLanguage]?.[source] ?? localizedAccessibility[currentLanguage]?.[source] ?? localizedPageTitles[currentLanguage]?.[source] ?? localizedAdditionalLabels[currentLanguage]?.[source] ?? localizedShortPhrases[currentLanguage]?.[source] ?? runtimeMessages[currentLanguage]?.[source]
    ?? localeMessages[currentLanguage]?.[normalizedSource] ?? localizedExtras[currentLanguage]?.[normalizedSource] ?? localizedLateExtras[currentLanguage]?.[normalizedSource] ?? localizedThemeLabels[currentLanguage]?.[normalizedSource] ?? localizedAccessibility[currentLanguage]?.[normalizedSource] ?? localizedPageTitles[currentLanguage]?.[normalizedSource] ?? localizedAdditionalLabels[currentLanguage]?.[normalizedSource] ?? localizedShortPhrases[currentLanguage]?.[normalizedSource] ?? runtimeMessages[currentLanguage]?.[normalizedSource];
  if (direct) return direct;
  for (const [pattern, render] of dynamicMessageRules[currentLanguage] || []) {
    const match = source.match(pattern);
    if (match) return render(...match.slice(1));
  }
  const accessibilityRule = dynamicAccessibilityRules[currentLanguage];
  if (accessibilityRule) {
    const accessibilityMatch = source.match(accessibilityRule[0]);
    if (accessibilityMatch) return accessibilityRule[1](accessibilityMatch[1]);
  }
  return source;
}

function applyLocale() {
  const locale = languageCatalog[currentLanguage] || languageCatalog.en;
  document.documentElement.lang = currentLanguage;
  document.documentElement.dir = locale.direction;
  document.title = translateText(document.title);

  document.querySelectorAll('[data-l10n]').forEach((element) => {
    element.textContent = translateText(element.dataset.l10n);
  });

  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement.closest('[data-l10n-skip]') || node.parentElement.closest('[data-l10n]')) continue;
    const source = node.nodeValue.replace(/\s+/g, ' ').trim();
    if (!source) continue;
    const translated = translateText(source);
    if (translated !== source) node.nodeValue = node.nodeValue.replace(source, translated);
  }

  document.querySelectorAll('[placeholder],[aria-label],[title],[data-message]').forEach((element) => {
    for (const attribute of ['placeholder', 'aria-label', 'title', 'data-message']) {
      const source = element.getAttribute(attribute);
      if (source) element.setAttribute(attribute, translateText(source));
    }
  });
}

function setLanguage(language) {
  if (!Object.hasOwn(languageCatalog, language)) return;
  currentLanguage = language;
  try {
    localStorage.setItem('muvy-language', language);
  } catch {
    // The active page still changes language for this visit.
  }
  applyLocale();
}

window.MUVYLocale = {
  languages: languageCatalog,
  get currentLanguage() { return currentLanguage; },
  getLanguageName(language = currentLanguage) { return languageCatalog[language]?.native || languageCatalog.en.native; },
  getTMDBLanguage(language = currentLanguage) { return languageCatalog[language]?.tmdb || languageCatalog.en.tmdb; },
  t: translateText,
  setLanguage,
  apply: applyLocale,
};

applyLocale();
